def pilotTheta (p ε : ℝ) (m : ℕ → ℕ) {n : ℕ}
    (z : Transcript (pilotOutputFamily n)) : TrialParameter :=
  let δ := (m n + 2 : ℝ)⁻¹
  let invFreq (k : Fin 4) :=
    ((Real.exp ε + 3) * pilotFrequency m z k - 1) /
      (Real.exp ε - 1)
  fun a =>
    if a = 0 then clipInterior δ (invFreq 1 / controlProb p)
    else clipInterior δ (invFreq 3 / p)

